-- SAFE review township repair batch: MMR001 / Kachin
-- Project locghyuranqaqsnbxflc; generated 2026-07-24.
-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _safe_review_results (
    group_id text PRIMARY KEY,
    township_id bigint NOT NULL,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (status IN ('updated', 'skipped')),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0039';
    v_target_id constant bigint := 6584;
    v_expected_name constant text := 'မံစီမြို့နယ်';
    v_mimu_pcode constant text := 'MMR001013';
    v_expected_parent_id constant bigint := 6594;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := 'c19fed87735219eff9a5b228b31e35e0';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မံစီမြို့နယ်","centroid":{"coordinates":[97.29555023001951,23.9183825],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996700","geometry_source":null,"id":6584,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"မံစီမြို့နယ်","area_m2":2894335965.939952,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4776,"is_primary":true,"language_code":"und","name":"မံစီမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4777,"is_primary":true,"language_code":"en","name":"Mansi Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4778,"is_primary":true,"language_code":"my","name":"မံစီမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4779,"is_primary":false,"language_code":"und","name":"မံစီမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"မံစီမြို့နယ်","boundary":"administrative","name":"မံစီမြို့နယ်","name:en":"Mansi Township","name:my":"မံစီမြို့နယ်","wikidata":"Q6751741","wikipedia":"en:Mansi Township"},"wikidata":"Q6751741","wikipedia":"en:Mansi Township"},"parent_id":6594,"public_id":"7a674913-c9d6-443f-8c1a-a9b3a4eff384","reference_source":null,"slug":"osm:R:5996700","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4776,"is_primary":true,"language_code":"und","name":"မံစီမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4777,"is_primary":true,"language_code":"en","name":"Mansi Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4778,"is_primary":true,"language_code":"my","name":"မံစီမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13087,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996700","id":4779,"is_primary":false,"language_code":"und","name":"မံစီမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996700","raw_id":11075,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996700","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11075,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1583","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0040';
    v_target_id constant bigint := 6593;
    v_expected_name constant text := 'မိုးမောက်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR001012';
    v_expected_parent_id constant bigint := 6594;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := 'eee8c1ddd4b6ec9965c2ede2af50fff1';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မိုးမောက်မြို့နယ်","centroid":{"coordinates":[97.38668552064931,24.532504250000002],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996725","geometry_source":null,"id":6593,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"မိုးမောက်မြို့နယ်","area_m2":2680756227.6400456,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4808,"is_primary":true,"language_code":"und","name":"မိုးမောက်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4809,"is_primary":true,"language_code":"en","name":"Momauk Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4810,"is_primary":true,"language_code":"my","name":"မိုးမောက်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4811,"is_primary":false,"language_code":"und","name":"မိုးမောက်မြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"မိုးမောက်မြို့နယ်","boundary":"administrative","name":"မိုးမောက်မြို့နယ်","name:en":"Momauk Township","name:my":"မိုးမောက်မြို့နယ်","wikidata":"Q6897037","wikipedia":"en:Momauk Township"},"wikidata":"Q6897037","wikipedia":"en:Momauk Township"},"parent_id":6594,"public_id":"9cd1afaa-7da3-4888-94bd-620bc717726e","reference_source":null,"slug":"osm:R:5996725","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4808,"is_primary":true,"language_code":"und","name":"မိုးမောက်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4809,"is_primary":true,"language_code":"en","name":"Momauk Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4810,"is_primary":true,"language_code":"my","name":"မိုးမောက်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13096,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996725","id":4811,"is_primary":false,"language_code":"und","name":"မိုးမောက်မြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996725","raw_id":11085,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996725","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11085,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1592","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0025';
    v_target_id constant bigint := 6623;
    v_expected_name constant text := 'ဝိုင်းမော်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR001002';
    v_expected_parent_id constant bigint := 6622;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := 'bac19f5e5979debab8b6a46e3dd66f92';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဝိုင်းမော်မြို့နယ်","centroid":{"coordinates":[97.5453049042316,25.225486],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996876","geometry_source":null,"id":6623,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"ဝိုင်းမော်မြို့နယ်","area_m2":5001646603.580158,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4906,"is_primary":true,"language_code":"und","name":"ဝိုင်းမော်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4907,"is_primary":true,"language_code":"en","name":"Waingmaw","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4908,"is_primary":false,"language_code":"und","name":"ဝိုင်းမော်မြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"ဝိုင်းမော်မြို့နယ်","boundary":"administrative","name":"ဝိုင်းမော်မြို့နယ်","name:en":"Waingmaw","wikidata":"Q7960163","wikipedia":"en:Waingmaw Township"},"wikidata":"Q7960163","wikipedia":"en:Waingmaw Township"},"parent_id":6622,"public_id":"ba395666-afb8-486b-856c-2240e02e0ab1","reference_source":null,"slug":"osm:R:5996876","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4906,"is_primary":true,"language_code":"und","name":"ဝိုင်းမော်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4907,"is_primary":true,"language_code":"en","name":"Waingmaw","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13126,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996876","id":4908,"is_primary":false,"language_code":"und","name":"ဝိုင်းမော်မြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996876","raw_id":11115,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996876","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11115,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1622","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0011';
    v_target_id constant bigint := 6681;
    v_expected_name constant text := 'နောင်မွန်းမြို့နယ်';
    v_mimu_pcode constant text := 'MMR001017';
    v_expected_parent_id constant bigint := 6682;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := '0be6bac1d71d9d54291e59b51b83c8d4';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"နောင်မွန်းမြို့နယ်","centroid":{"coordinates":[97.8085162678939,27.9287103],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996769","geometry_source":null,"id":6681,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Nawngmun;Nogmung;Nogmung Township","area_m2":8110444378.194798,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5085,"is_primary":true,"language_code":"und","name":"နောင်မွန်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5086,"is_primary":true,"language_code":"en","name":"Nawngmun Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5087,"is_primary":true,"language_code":"my","name":"နောင်မွန်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5088,"is_primary":false,"language_code":"und","name":"Nawngmun;Nogmung;Nogmung Township","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Nawngmun;Nogmung;Nogmung Township","boundary":"administrative","name":"နောင်မွန်းမြို့နယ်","name:en":"Nawngmun Township","name:my":"နောင်မွန်းမြို့နယ်","wikidata":"Q7047499","wikipedia":"en:Nogmung Township"},"wikidata":"Q7047499","wikipedia":"en:Nogmung Township"},"parent_id":6682,"public_id":"39aca498-4c51-49b3-ae50-50cc7ef46888","reference_source":null,"slug":"osm:R:5996769","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5085,"is_primary":true,"language_code":"und","name":"နောင်မွန်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5086,"is_primary":true,"language_code":"en","name":"Nawngmun Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5087,"is_primary":true,"language_code":"my","name":"နောင်မွန်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13184,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996769","id":5088,"is_primary":false,"language_code":"und","name":"Nawngmun;Nogmung;Nogmung Township","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996769","raw_id":11174,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996769","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11174,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1680","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0014';
    v_target_id constant bigint := 6685;
    v_expected_name constant text := 'ပူတာအိုမြို့နယ်';
    v_mimu_pcode constant text := 'MMR001014';
    v_expected_parent_id constant bigint := 6682;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := 'a3ebf58cad79045945c7a954367d05aa';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ပူတာအိုမြို့နယ်","centroid":{"coordinates":[97.2713408820032,27.34774535],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996806","geometry_source":null,"id":6685,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Puta-O;Putao","area_m2":6136214408.566616,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5099,"is_primary":true,"language_code":"und","name":"ပူတာအိုမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5100,"is_primary":true,"language_code":"en","name":"Putao Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5101,"is_primary":true,"language_code":"my","name":"ပူတာအိုမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5102,"is_primary":false,"language_code":"und","name":"Puta-O;Putao","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Puta-O;Putao","boundary":"administrative","name":"ပူတာအိုမြို့နယ်","name:en":"Putao Township","name:my":"ပူတာအိုမြို့နယ်","wikidata":"Q7262179","wikipedia":"en:Putao Township"},"wikidata":"Q7262179","wikipedia":"en:Putao Township"},"parent_id":6682,"public_id":"505814e4-7afc-4d8a-aab2-96607200bf17","reference_source":null,"slug":"osm:R:5996806","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5099,"is_primary":true,"language_code":"und","name":"ပူတာအိုမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5100,"is_primary":true,"language_code":"en","name":"Putao Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5101,"is_primary":true,"language_code":"my","name":"ပူတာအိုမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13188,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996806","id":5102,"is_primary":false,"language_code":"und","name":"Puta-O;Putao","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996806","raw_id":11180,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996806","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11180,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1684","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0031';
    v_target_id constant bigint := 6687;
    v_expected_name constant text := 'ခေါင်လန်ဖူးမြို့နယ်';
    v_mimu_pcode constant text := 'MMR001018';
    v_expected_parent_id constant bigint := 6682;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := '5766731142c0b99f42e609292b0a2403';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ခေါင်လန်ဖူးမြို့နယ်","centroid":{"coordinates":[98.40679812833177,27.187680399999998],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996651","geometry_source":null,"id":6687,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"ခေါင်လန်ဖူးမြို့နယ်","area_m2":5325574628.71266,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5107,"is_primary":true,"language_code":"und","name":"ခေါင်လန်ဖူး","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5108,"is_primary":true,"language_code":"en","name":"Kawnglanghpu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5109,"is_primary":true,"language_code":"my","name":"ခေါင်လန်ဖူးမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5110,"is_primary":false,"language_code":"und","name":"ခေါင်လန်ဖူးမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"ခေါင်လန်ဖူးမြို့နယ်","boundary":"administrative","name":"ခေါင်လန်ဖူး","name:en":"Kawnglanghpu Township","name:my":"ခေါင်လန်ဖူးမြို့နယ်","wikidata":"Q6380058","wikipedia":"en:Kawnglanghpu Township"},"wikidata":"Q6380058","wikipedia":"en:Kawnglanghpu Township"},"parent_id":6682,"public_id":"096f8dca-1a90-4741-a264-840963b4794f","reference_source":null,"slug":"osm:R:5996651","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5107,"is_primary":true,"language_code":"und","name":"ခေါင်လန်ဖူး","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5108,"is_primary":true,"language_code":"en","name":"Kawnglanghpu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5109,"is_primary":true,"language_code":"my","name":"ခေါင်လန်ဖူးမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13190,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996651","id":5110,"is_primary":false,"language_code":"und","name":"ခေါင်လန်ဖူးမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996651","raw_id":11182,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996651","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11182,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1686","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0013';
    v_target_id constant bigint := 6690;
    v_expected_name constant text := 'ချီဖွေမြို့နယ်';
    v_mimu_pcode constant text := 'MMR001005';
    v_expected_parent_id constant bigint := 6689;
    v_expected_state_id constant bigint := 6667;
    v_expected_geom_hash constant text := '819a8c1e2514d26c21b29078da707b8f';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ချီဖွေမြို့နယ်","centroid":{"coordinates":[98.48436619692296,26.0282727],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996589","geometry_source":null,"id":6690,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"ချီဖွေမြို့နယ်","area_m2":3397628989.2853737,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5118,"is_primary":true,"language_code":"und","name":"ချီဖွေမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5119,"is_primary":true,"language_code":"en","name":"Chipwi Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5120,"is_primary":true,"language_code":"my","name":"ချီဖွေမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5121,"is_primary":false,"language_code":"und","name":"ချီဖွေမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"ချီဖွေမြို့နယ်","boundary":"administrative","name":"ချီဖွေမြို့နယ်","name:en":"Chipwi Township","name:my":"ချီဖွေမြို့နယ်","wikidata":"Q5101750","wikipedia":"en:Chipwi Township"},"wikidata":"Q5101750","wikipedia":"en:Chipwi Township"},"parent_id":6689,"public_id":"93c52e90-af03-420b-aea3-2a4ae723f1e1","reference_source":null,"slug":"osm:R:5996589","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5118,"is_primary":true,"language_code":"und","name":"ချီဖွေမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5119,"is_primary":true,"language_code":"en","name":"Chipwi Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5120,"is_primary":true,"language_code":"my","name":"ချီဖွေမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13193,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996589","id":5121,"is_primary":false,"language_code":"und","name":"ချီဖွေမြို့နယ်","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996589","raw_id":11185,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996589","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11185,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1689","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $batch_verify$
BEGIN
    IF (SELECT count(*) FROM _safe_review_results) <> 7 THEN
        RAISE EXCEPTION 'Expected 7 result rows';
    END IF;
    IF EXISTS (
        SELECT 1 FROM _safe_review_results
        WHERE status = 'updated' AND new_overlap_m2 > 100.0
    ) THEN
        RAISE EXCEPTION 'Batch contains a meaningful new overlap';
    END IF;
END
$batch_verify$;

SELECT * FROM _safe_review_results ORDER BY township_id;
COMMIT;

