    v_expected_geom_hash constant text := '7a96e2815bac6332792cf5b448fcce64';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မြဝတီမြို့နယ်","centroid":{"coordinates":[98.49448513768631,16.56501595],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996751","geometry_source":null,"id":5033,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":3134943321.2793207,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":11526,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996751","id":61,"is_primary":true,"language_code":"und","name":"မြဝတီမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996751","raw_id":9496,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11526,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996751","id":62,"is_primary":true,"language_code":"en","name":"Myawaddy Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996751","raw_id":9496,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11526,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996751","id":63,"is_primary":true,"language_code":"my","name":"မြဝတီမြို့နယ်","name_type":"official","normalized_data":{"source_tag"