    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဘုတ်ပြင်းမြို့နယ်","centroid":{"coordinates":[98.31187089111083,11.219682500000001],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996580","geometry_source":null,"id":5035,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":17558140854.208958,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":11528,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996580","id":67,"is_primary":true,"language_code":"und","name":"ဘုတ်ပြင်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996580","raw_id":9498,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11528,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996580","id":68,"is_primary":true,"language_code":"en","name":"Bokpyin Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996580","raw_id":9498,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11528,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996580","id":69,"is_primary":true,"language_code":"my","name":"ဘုတ်ပြင်းမြို့နယ်","name_type":"official","normalized_d