-- SAFE review township repair batch: MMR012 / Rakhine
-- Project locghyuranqaqsnbxflc; generated 2026-07-24.
-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _safe_review_results (
    group_id text PRIMARY KEY,
    township_id bigint NOT NULL,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (status IN ('updated', 'skipped')),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0020';
    v_target_id constant bigint := 5199;
    v_expected_name constant text := 'ကျောက်ဖြူ';
    v_mimu_pcode constant text := 'MMR012011';
    v_expected_parent_id constant bigint := 7185;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'b3228bfcaed3f80d099c578626e320d4';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ကျောက်ဖြူ","centroid":{"coordinates":[93.75918820309141,19.43363135],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996666","geometry_source":null,"id":5199,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Kyaukpyu","area_m2":1169359924.531223,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":561,"is_primary":true,"language_code":"und","name":"ကျောက်ဖြူ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":562,"is_primary":true,"language_code":"en","name":"Kyaukpyu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":563,"is_primary":false,"language_code":"und","name":"Kyaukpyu","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Kyaukpyu","boundary":"administrative","name":"ကျောက်ဖြူ","name:en":"Kyaukpyu Township","wikidata":"Q6450780","wikipedia":"en:Kyaukpyu Township"},"wikidata":"Q6450780","wikipedia":"en:Kyaukpyu Township"},"parent_id":7185,"public_id":"c25fa666-5a35-4e95-af46-319665641346","reference_source":null,"slug":"osm:R:5996666","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":561,"is_primary":true,"language_code":"und","name":"ကျောက်ဖြူ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":562,"is_primary":true,"language_code":"en","name":"Kyaukpyu Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":11701,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996666","id":563,"is_primary":false,"language_code":"und","name":"Kyaukpyu","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996666","raw_id":11716,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996666","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11716,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"197","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0005';
    v_target_id constant bigint := 6897;
    v_expected_name constant text := 'မြေပုံ';
    v_mimu_pcode constant text := 'MMR012006';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '00d7eee7fff7adb1926e347f869c2478';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မြေပုံ","centroid":{"coordinates":[93.537769989,20.06453735],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996752","geometry_source":null,"id":6897,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Myebon","area_m2":1968813044.571253,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5784,"is_primary":true,"language_code":"und","name":"မြေပုံ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5785,"is_primary":true,"language_code":"en","name":"Myebon Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5786,"is_primary":false,"language_code":"und","name":"Myebon","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Myebon","boundary":"administrative","name":"မြေပုံ","name:en":"Myebon Township","wikidata":"Q6947278","wikipedia":"en:Myebon Township"},"wikidata":"Q6947278","wikipedia":"en:Myebon Township"},"parent_id":7005,"public_id":"ba2d7ed8-46c2-4600-82b0-2ce891dea030","reference_source":null,"slug":"osm:R:5996752","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5784,"is_primary":true,"language_code":"und","name":"မြေပုံ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5785,"is_primary":true,"language_code":"en","name":"Myebon Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13400,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996752","id":5786,"is_primary":false,"language_code":"und","name":"Myebon","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996752","raw_id":11743,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996752","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11743,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1896","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0046';
    v_target_id constant bigint := 6950;
    v_expected_name constant text := 'မင်းပြား';
    v_mimu_pcode constant text := 'MMR012005';
    v_expected_parent_id constant bigint := 7005;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'c5b7fa88725ccbd9ea4ea7013e4e8a2b';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မင်းပြား","centroid":{"coordinates":[93.520913555,20.54870525],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996714","geometry_source":null,"id":6950,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Minbya","area_m2":3420998007.473623,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5952,"is_primary":true,"language_code":"und","name":"မင်းပြား","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5953,"is_primary":true,"language_code":"en","name":"Minbya Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5954,"is_primary":false,"language_code":"und","name":"Minbya","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Minbya","boundary":"administrative","name":"မင်းပြား","name:en":"Minbya Township","wikidata":"Q6863310","wikipedia":"en:Minbya Township"},"wikidata":"Q6863310","wikipedia":"en:Minbya Township"},"parent_id":7005,"public_id":"21053ec0-3c86-497e-9aed-d82667ca8b8a","reference_source":null,"slug":"osm:R:5996714","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5952,"is_primary":true,"language_code":"und","name":"မင်းပြား","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5953,"is_primary":true,"language_code":"en","name":"Minbya Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13453,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996714","id":5954,"is_primary":false,"language_code":"und","name":"Minbya","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996714","raw_id":11454,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996714","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11454,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1949","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0129';
    v_target_id constant bigint := 6965;
    v_expected_name constant text := 'ဘူးသီးတောင်';
    v_mimu_pcode constant text := 'MMR012010';
    v_expected_parent_id constant bigint := 6967;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '3eceb3091272f38fd36c8f9297490f42';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဘူးသီးတောင်","centroid":{"coordinates":[92.54131621318032,20.9895873],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996583","geometry_source":null,"id":6965,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","area_m2":2230349942.0347195,"boundary":"administrative","level_correction_applied":false,"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5997,"is_primary":true,"language_code":"und","name":"ဘူးသီးတောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5998,"is_primary":true,"language_code":"en","name":"Buthidaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5999,"is_primary":false,"language_code":"und","name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","boundary":"administrative","name":"ဘူးသီးတောင်","name:en":"Buthidaung Township","wikidata":"Q5002516","wikipedia":"en:Buthidaung Township"},"wikidata":"Q5002516","wikipedia":"en:Buthidaung Township"},"parent_id":6967,"public_id":"775b6bc4-da21-4482-b9b3-c6f3f34965f1","reference_source":null,"slug":"osm:R:5996583","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5997,"is_primary":true,"language_code":"und","name":"ဘူးသီးတောင်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5998,"is_primary":true,"language_code":"en","name":"Buthidaung Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13468,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996583","id":5999,"is_primary":false,"language_code":"und","name":"Buthidaung;ဘူးသီးတောင်မြို့နယ","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996583","raw_id":11470,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996583","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11470,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1964","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('AQYAAAABAAAAAQMAAAABAAAACwAAAEHcIE/LJ1dA3EIh2XlBNUDLwFzmzydXQMc/fRUqQTVAajbqfNMnV0DaSMj2EEE1QMruE1HdJ1dAwcLu4MxANUBAAjVr3ydXQPXDY5pEQDVApiye1d0nV0D600Z1OkA1QOW1ErrLJ1dADsepjDVANUCd5i7TwCdXQIzdmWQ/QDVAzc6id6onV0CeXPhmQEA1QEhytZicJ1dAXCtSbD9ANUBB3CBPyydXQNxCIdl5QTVA', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0022';
    v_target_id constant bigint := 6966;
    v_expected_name constant text := 'မောင်တောမြို့နယ်';
    v_mimu_pcode constant text := 'MMR012009';
    v_expected_parent_id constant bigint := 6967;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '7b05e356a21461b0557ffb30e9280637';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"မောင်တောမြို့နယ်","centroid":{"coordinates":[92.31205432236422,20.966861350000002],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996705","geometry_source":null,"id":6966,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":1460324081.3759391,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6000,"is_primary":true,"language_code":"und","name":"မောင်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6001,"is_primary":true,"language_code":"en","name":"Maungdaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","boundary":"administrative","name":"မောင်တော","name:en":"Maungdaw Township","wikidata":"Q6792576","wikipedia":"en:Maungdaw Township"},"wikidata":"Q6792576","wikipedia":"en:Maungdaw Township"},"parent_id":6967,"public_id":"6620e7fe-f387-484d-8ebb-58f02975674e","reference_source":null,"slug":"osm:R:5996705","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6000,"is_primary":true,"language_code":"und","name":"မောင်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13469,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996705","id":6001,"is_primary":true,"language_code":"en","name":"Maungdaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996705","raw_id":11471,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"}],"osm_feature_type":"R","osm_id":"5996705","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11471,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1965","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0023';
    v_target_id constant bigint := 7000;
    v_expected_name constant text := 'ပေါက်တော';
    v_mimu_pcode constant text := 'MMR012007';
    v_expected_parent_id constant bigint := 6988;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '2d289a397287c663608a7912f35b1bca';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ပေါက်တော","centroid":{"coordinates":[93.094926934,20.26564535],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996794","geometry_source":null,"id":7000,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Pauktaw","area_m2":932785096.0178319,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6091,"is_primary":true,"language_code":"und","name":"ပေါက်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6092,"is_primary":true,"language_code":"en","name":"Pauktaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6093,"is_primary":false,"language_code":"und","name":"Pauktaw","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Pauktaw","boundary":"administrative","name":"ပေါက်တော","name:en":"Pauktaw Township","wikidata":"Q7148891","wikipedia":"en:Pauktaw Township"},"wikidata":"Q7148891","wikipedia":"en:Pauktaw Township"},"parent_id":6988,"public_id":"c7e446b4-6cbe-490a-8008-e766aa5f520e","reference_source":null,"slug":"osm:R:5996794","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6091,"is_primary":true,"language_code":"und","name":"ပေါက်တော","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6092,"is_primary":true,"language_code":"en","name":"Pauktaw Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13503,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996794","id":6093,"is_primary":false,"language_code":"und","name":"Pauktaw","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996794","raw_id":11511,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996794","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11511,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1999","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0010';
    v_target_id constant bigint := 7098;
    v_expected_name constant text := 'အမ်း';
    v_mimu_pcode constant text := 'MMR012014';
    v_expected_parent_id constant bigint := 7097;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '949e363f717888cbb4945390a9e715db';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"အမ်း","centroid":{"coordinates":[94.034134806,19.9236582],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996569","geometry_source":null,"id":7098,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Ann","area_m2":6260060821.843531,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6401,"is_primary":true,"language_code":"und","name":"အမ်း","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6402,"is_primary":true,"language_code":"en","name":"Ann Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6403,"is_primary":false,"language_code":"und","name":"Ann","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Ann","boundary":"administrative","name":"အမ်း","name:en":"Ann Township","wikidata":"Q4766709","wikipedia":"en:Ann Township"},"wikidata":"Q4766709","wikipedia":"en:Ann Township"},"parent_id":7097,"public_id":"23fcc105-16fc-44f9-9a18-71955d34e0f2","reference_source":null,"slug":"osm:R:5996569","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6401,"is_primary":true,"language_code":"und","name":"အမ်း","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6402,"is_primary":true,"language_code":"en","name":"Ann Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13601,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996569","id":6403,"is_primary":false,"language_code":"und","name":"Ann","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996569","raw_id":11611,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996569","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11611,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"2097","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0012';
    v_target_id constant bigint := 7109;
    v_expected_name constant text := 'တောင်ကုတ်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR012016';
    v_expected_parent_id constant bigint := 7108;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '6d97a1c975e927e0a155112fcd3bc678';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"တောင်ကုတ်မြို့နယ်","centroid":{"coordinates":[94.3788930648353,19.0801413],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996873","geometry_source":null,"id":7109,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Toungup","area_m2":4792638551.956879,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6435,"is_primary":true,"language_code":"und","name":"တောင်ကုတ်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6436,"is_primary":true,"language_code":"en","name":"Toungup Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6437,"is_primary":false,"language_code":"und","name":"Toungup","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Toungup","boundary":"administrative","name":"တောင်ကုတ်မြို့နယ်","name:en":"Toungup Township","wikidata":"Q7688765","wikipedia":"en:Toungup Township"},"wikidata":"Q7688765","wikipedia":"en:Toungup Township"},"parent_id":7108,"public_id":"30c03d09-353b-4f6f-bbe1-a748be68445c","reference_source":null,"slug":"osm:R:5996873","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6435,"is_primary":true,"language_code":"und","name":"တောင်ကုတ်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6436,"is_primary":true,"language_code":"en","name":"Toungup Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13612,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996873","id":6437,"is_primary":false,"language_code":"und","name":"Toungup","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996873","raw_id":11626,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996873","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11626,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"2108","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0067';
    v_target_id constant bigint := 7176;
    v_expected_name constant text := 'သံတွဲမြို့နယ်';
    v_mimu_pcode constant text := 'MMR012015';
    v_expected_parent_id constant bigint := 7173;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'a88e5efb0627d87b009647a4080c5c05';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"သံတွဲမြို့နယ်","centroid":{"coordinates":[94.6166112137021,18.3448015],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996859","geometry_source":null,"id":7176,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Thandwe","area_m2":3494252540.9893255,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6652,"is_primary":true,"language_code":"und","name":"သံတွဲ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6653,"is_primary":true,"language_code":"en","name":"Thandwe Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6654,"is_primary":false,"language_code":"und","name":"Thandwe","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Thandwe","boundary":"administrative","name":"သံတွဲ","name:en":"Thandwe Township","wikidata":"Q7710228","wikipedia":"en:Thandwe Township"},"wikidata":"Q7710228","wikipedia":"en:Thandwe Township"},"parent_id":7173,"public_id":"617a076d-421a-4c29-a5f9-e118e2357ee2","reference_source":null,"slug":"osm:R:5996859","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6652,"is_primary":true,"language_code":"und","name":"သံတွဲ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6653,"is_primary":true,"language_code":"en","name":"Thandwe Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13679,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996859","id":6654,"is_primary":false,"language_code":"und","name":"Thandwe","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996859","raw_id":11699,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996859","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11699,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"2175","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0034';
    v_target_id constant bigint := 7184;
    v_expected_name constant text := 'ရမ်းဗြဲ';
    v_mimu_pcode constant text := 'MMR012013';
    v_expected_parent_id constant bigint := 7185;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := '34fdd748431e2f43e009d8083487da13';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ရမ်းဗြဲ","centroid":{"coordinates":[93.848206862,19.123229],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996814","geometry_source":null,"id":7184,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":false,"normalized_data":{"admin_level":"7","alt_name":"Ramree","area_m2":1171076276.1387765,"boundary":"administrative","level_correction_applied":false,"manual_admin_area_type_cleanup_20260618":{"admin_area_type_code":"township","admin_level_code":"township","reason":"Reviewed from 104 unclassified rows; township-level boundary for map coverage","updated_at":"2026-06-18T04:18:50.764623+00:00"},"mapped_admin_level_code":"ward_village_tract","names":[{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6675,"is_primary":true,"language_code":"und","name":"ရမ်းဗြဲ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6676,"is_primary":true,"language_code":"en","name":"Ramree Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6677,"is_primary":false,"language_code":"und","name":"Ramree","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","tags":{"admin_level":"7","alt_name":"Ramree","boundary":"administrative","name":"ရမ်းဗြဲ","name:en":"Ramree Township","wikidata":"Q7290087","wikipedia":"en:Ramree Township"},"wikidata":"Q7290087","wikipedia":"en:Ramree Township"},"parent_id":7185,"public_id":"73a6ff73-0d1a-4839-b932-af06688c50f9","reference_source":null,"slug":"osm:R:5996814","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6675,"is_primary":true,"language_code":"und","name":"ရမ်းဗြဲ","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6676,"is_primary":true,"language_code":"en","name":"Ramree Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13687,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996814","id":6677,"is_primary":false,"language_code":"und","name":"Ramree","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996814","raw_id":11713,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996814","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11713,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"2183","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"unverified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0108';
    v_target_id constant bigint := 7188;
    v_expected_name constant text := 'ဂွမြို့နယ်';
    v_mimu_pcode constant text := 'MMR012017';
    v_expected_parent_id constant bigint := 7173;
    v_expected_state_id constant bigint := 6722;
    v_expected_geom_hash constant text := 'be8776cc5110f5ec7186b24187613133';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဂွမြို့နယ်","centroid":{"coordinates":[94.70526484912213,17.737702249999998],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:5996607","geometry_source":null,"id":7188,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","alt_name":"Gwa","area_m2":2258045545.5627747,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6688,"is_primary":true,"language_code":"und","name":"ဂွမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6689,"is_primary":true,"language_code":"en","name":"Gwa Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6690,"is_primary":true,"language_code":"my","name":"ဂွမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6691,"is_primary":false,"language_code":"und","name":"Gwa","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","parent_hierarchy_fix_20260618":{"new_parent_id":7173,"old_parent_id":6722,"rule":"township_parent_must_be_district","updated_at":"2026-06-18T04:20:14.943578+00:00"},"semantic_level_code":"township","tags":{"admin_level":"7","alt_name":"Gwa","boundary":"administrative","name":"ဂွမြို့နယ်","name:en":"Gwa Township","name:my":"ဂွမြို့နယ်","wikidata":"Q5623218","wikipedia":"en:Gwa Township"},"wikidata":"Q5623218","wikipedia":"en:Gwa Township"},"parent_id":7173,"public_id":"c2000745-f2c8-42a4-b31d-a10beb1f5db9","reference_source":null,"slug":"osm:R:5996607","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6688,"is_primary":true,"language_code":"und","name":"ဂွမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6689,"is_primary":true,"language_code":"en","name":"Gwa Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6690,"is_primary":true,"language_code":"my","name":"ဂွမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"},{"admin_area_candidate_id":13691,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:5996607","id":6691,"is_primary":false,"language_code":"und","name":"Gwa","name_type":"alternate","normalized_data":{"source_tag":"alt_name"},"search_weight":80,"source_refs":{"osm_feature_type":"R","osm_id":"5996607","raw_id":11755,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"alt_name"},"source_tag":"alt_name"}],"osm_feature_type":"R","osm_id":"5996607","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":11755,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"2187","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $batch_verify$
BEGIN
    IF (SELECT count(*) FROM _safe_review_results) <> 11 THEN
        RAISE EXCEPTION 'Expected 11 result rows';
    END IF;
    IF EXISTS (
        SELECT 1 FROM _safe_review_results
        WHERE status = 'updated' AND new_overlap_m2 > 100.0
    ) THEN
        RAISE EXCEPTION 'Batch contains a meaningful new overlap';
    END IF;
END
$batch_verify$;

SELECT * FROM _safe_review_results ORDER BY township_id;
COMMIT;

-- ============================================================================
-- BATCH 8: MMR015 / Shan (North) (3 rows)
-- ============================================================================

-- SAFE review township repair batch: MMR015 / Shan (North)
