-- One-time repair: existing geom only; no inserts or metadata changes.
BEGIN;
SET LOCAL statement_timeout = '15min';
SET LOCAL lock_timeout = '30s';

CREATE TEMP TABLE _safe_review_results (
    group_id text PRIMARY KEY,
    township_id bigint NOT NULL,
    canonical_name text NOT NULL,
    mimu_pcode text NOT NULL,
    status text NOT NULL CHECK (status IN ('updated', 'skipped')),
    best_candidate_id bigint,
    best_score double precision,
    second_score double precision,
    area_added_m2 double precision NOT NULL DEFAULT 0,
    new_overlap_m2 double precision NOT NULL DEFAULT 0,
    reason text NOT NULL
) ON COMMIT DROP;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0088';
    v_target_id constant bigint := 6412;
    v_expected_name constant text := 'ရှင်းဝမ်မြို့နယ်';
    v_mimu_pcode constant text := 'MMR015023';
    v_expected_parent_id constant bigint := 6411;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := 'ebed3c89dd63108338b71ef4a1d3d539';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ရှင်းဝမ်မြို့နယ်","centroid":{"coordinates":[98.50743501167402,23.90134505],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:17024479","geometry_source":null,"id":6412,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":486096185.6899658,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":12915,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024479","id":4239,"is_primary":true,"language_code":"und","name":"ရှင်းဝမ်မြို့နယ် 兴旺区","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17024479","raw_id":10901,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12915,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024479","id":4240,"is_primary":true,"language_code":"en","name":"Xingwang Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17024479","raw_id":10901,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12915,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024479","id":4241,"is_primary":true,"language_code":"my","name":"ရှင်းဝမ်မြို့နယ်","name_type":"official","norm