:"ရှင်းဝမ်မြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17024479","raw_id":10901,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"}],"osm_feature_type":"R","osm_id":"17024479","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":10901,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1411","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0078';
    v_target_id constant bigint := 6416;
    v_expected_name constant text := 'တုန်းရှမ်းမြို့နယ်';
    v_mimu_pcode constant text := 'MMR015022';
    v_expected_parent_id constant bigint := 6411;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := '123bf97234225bd2384868ad98718f79';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"တုန်းရှမ်းမြို့နယ်","centroid":{"coordinates":[98.72747002398937,23.561160049999998],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:17816410","geometry_source":null,"id":6416,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":343580504.59712976,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4251,"is_primary":true,"language_code":"und","name":"တုန်းရှမ်းမြို့နယ် 东山区","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4252,"is_primary":true,"language_code":"en","name":"Dongshan Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4253,"is_primary":true,"language_code":"my","name":"တုန်းရှမ်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"}],"osm_admin_level":"7","osm_level_code":"ward_village_tract","semantic_level_code":"township","tags":{"admin_level":"7","boundary":"administrative","name":"တုန်းရှမ်းမြို့နယ် 东山区","name:en":"Dongshan Township","name:my":"တုန်းရှမ်းမြို့နယ်","wikidata":"Q130270244","wikipedia":"zh:东山区 (果敢县)"},"wikidata":"Q130270244","wikipedia":"zh:东山区 (果敢县)"},"parent_id":6411,"public_id":"f29c1dbd-5171-4e4b-8510-7bbb6d01f62f","reference_source":null,"slug":"osm:R:17816410","source_license_status":"unknown","source_refs":{"entity_family":"admin_areas","names":[{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4251,"is_primary":true,"language_code":"und","name":"တုန်းရှမ်းမြို့နယ် 东山区","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4252,"is_primary":true,"language_code":"en","name":"Dongshan Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":12919,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17816410","id":4253,"is_primary":true,"language_code":"my","name":"တုန်းရှမ်းမြို့နယ်","name_type":"official","normalized_data":{"source_tag":"name:my"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17816410","raw_id":10905,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:my"},"source_tag":"name:my"}],"osm_feature_type":"R","osm_id":"17816410","promotion_path":"tools/data-pipeline/import-review-bulk-promotion/01_bulk_promote_admin_areas.sql","raw_id":10905,"raw_table":"raw_osm_polygons","region_code":"MM","review_batch_id":"3","review_candidate_id":"1415","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6},"source_type_id":1,"verification_note":null,"verification_status":"verified","verified_at":null,"verified_by":null}'::jsonb;
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_live_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
    v_best_candidate_id bigint;
    v_best_score double precision;
    v_second_score double precision;
    v_best_connected boolean;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_expected_name, v_mimu_pcode, 'skipped',
             'target is missing or no longer an active township');
        RETURN;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    IF v_before_other IS DISTINCT FROM v_expected_other THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'non-geometry row values changed after backup');
        RETURN;
    END IF;
    IF md5(encode(ST_AsEWKB(v_before.geom), 'hex')) IS DISTINCT FROM v_expected_geom_hash THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target geometry changed after backup');
        RETURN;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name
       OR v_before.parent_id IS DISTINCT FROM v_expected_parent_id THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'target identity or parent changed after approval');
        RETURN;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom)
       OR ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'current target geometry is invalid, empty, or wrong type/SRID');
        RETURN;
    END IF;

    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );
    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu)
       OR v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'MIMU or approved SAFE geometry is unusable');
        RETURN;
    END IF;

    -- Recompute immediately before this group. Earlier updates in this transaction
    -- are visible, so no already-filled SAFE surface can be added twice.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    JOIN ref.ref_admin_levels AS level ON level.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_mimu, v_current_union)),
            3
        )
    );
    v_live_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );
    IF v_live_patch IS NULL OR ST_IsEmpty(v_live_patch)
       OR ST_Area(ST_Transform(v_live_patch, 6933)) < 100.0 THEN
        INSERT INTO _safe_review_results
            (group_id, township_id, canonical_name, mimu_pcode, status, reason)
        VALUES
            (v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
             'latest approved live-gap intersection is empty or below 100 m2');
        RETURN;
    END IF;

    -- Geometry-only reranking. Names do not contribute. The intended recipient
    -- must still be first, connected to the live patch, score >= 60, and lead
    -- the second candidate by at least 10 points.
    WITH candidate_base AS (
        SELECT
            candidate.id,
            candidate.geom,
            candidate.parent_id,
            CASE
                WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                ELSE parent.parent_id
            END AS state_id,
            ST_Area(ST_Transform(candidate.geom, 6933)) AS core_area_m2,
            ST_Area(
                ST_Transform(
                    ST_CollectionExtract(ST_Intersection(candidate.geom, v_mimu), 3),
                    6933
                )
            ) AS intersection_m2,
            ST_Covers(v_mimu, ST_PointOnSurface(candidate.geom)) AS core_pos_in_mimu,
            ST_Covers(candidate.geom, ST_PointOnSurface(v_mimu)) AS mimu_pos_in_core,
            ST_Distance(
                ST_Transform(v_live_patch, 6933),
                ST_Transform(candidate.geom, 6933)
            ) AS distance_m,
            ST_Length(
                ST_Intersection(
                    ST_Boundary(ST_Transform(v_live_patch, 6933)),
                    ST_Boundary(ST_Transform(candidate.geom, 6933))
                )
            ) AS shared_boundary_m
        FROM core.core_admin_areas AS candidate
        JOIN ref.ref_admin_levels AS candidate_level
          ON candidate_level.id = candidate.admin_level_id
        LEFT JOIN core.core_admin_areas AS parent ON parent.id = candidate.parent_id
        LEFT JOIN ref.ref_admin_levels AS parent_level
          ON parent_level.id = parent.admin_level_id
        WHERE candidate.is_active IS TRUE
          AND candidate.deleted_at IS NULL
          AND lower(btrim(candidate_level.code)) = 'township'
          AND candidate.geom IS NOT NULL
          AND NOT ST_IsEmpty(candidate.geom)
          AND ST_IsValid(candidate.geom)
          AND (
              ST_Intersects(candidate.geom, v_mimu)
              OR (
                  CASE
                      WHEN lower(btrim(parent_level.code)) = 'state_region' THEN parent.id
                      ELSE parent.parent_id
                  END = v_expected_state_id
                  AND ST_DWithin(
                      ST_Transform(candidate.geom, 6933),
                      ST_Transform(v_mimu, 6933),
                      20000.0
                  )
              )
          )
    ),
    scored AS (
        SELECT
            base.id,
            base.distance_m,
            base.shared_boundary_m,
            (
                30.0 * LEAST(1.0, base.intersection_m2 / NULLIF(base.core_area_m2, 0))
                + 25.0 * (
                    base.intersection_m2
                    / NULLIF(sum(base.intersection_m2) OVER (), 0)
                )
                + 12.0 * LEAST(
                    1.0,
                    base.intersection_m2
                    / NULLIF(ST_Area(ST_Transform(v_mimu, 6933)), 0)
                )
                + 8.0 * (
                    (base.core_pos_in_mimu::int + base.mimu_pos_in_core::int) / 2.0
                )
                + 4.0 * CASE WHEN base.parent_id = v_expected_parent_id THEN 1 ELSE 0 END
                + 2.0 * CASE WHEN base.state_id = v_expected_state_id THEN 1 ELSE 0 END
                + CASE
                    WHEN base.distance_m <= 5.0 OR base.shared_boundary_m > 0
                        THEN 12.0
                    ELSE 12.0 * exp(-base.distance_m / 500.0)
                  END
                + 6.0 * exp(-base.distance_m / 1000.0)
            ) AS score,
            (base.distance_m <= 5.0 OR base.shared_boundary_m > 0) AS connected
        FROM candidate_base AS base
    ),
    ranked AS (
        SELECT
            id,
            score,
            connected,
            row_number() OVER (
                ORDER BY score DESC, shared_boundary_m DESC, distance_m ASC, id
            ) AS position
        FROM scored
    )
    SELECT
        max(id) FILTER (WHERE position = 1),
        max(score) FILTER (WHERE position = 1),
        coalesce(max(score) FILTER (WHERE position = 2), 0),
        coalesce(bool_or(connected) FILTER (WHERE position = 1), false)
    INTO v_best_candidate_id, v_best_score, v_second_score, v_best_connected
    FROM ranked
    WHERE position <= 2;

    IF v_best_candidate_id IS DISTINCT FROM v_target_id
       OR coalesce(v_best_score, 0) < 60.0
       OR coalesce(v_best_score, 0) - coalesce(v_second_score, 0) < 10.0
       OR NOT coalesce(v_best_connected, false) THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, coalesce(v_best_score, 0), coalesce(v_second_score, 0),
            'intended recipient is no longer clearly dominant and connected'
        );
        RETURN;
    END IF;

    -- A micrometre-scale inward collar keeps the additive components disjoint
    -- from the verbatim old geometry. This lets ST_Collect preserve every old
    -- coordinate while avoiding an invalid MultiPolygon at shared edges.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Buffer(v_live_patch, -1e-11)),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Difference(v_live_patch, v_safe_patch), 3),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL OR ST_IsEmpty(v_safe_patch)
       OR NOT ST_IsValid(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0
       OR v_boundary_collar_m2 > 1.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score,
            format('safe boundary collar is invalid or removed %s m2', v_boundary_collar_m2)
        );
        RETURN;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)), 0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)), 0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(other.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS other
    JOIN ref.ref_admin_levels AS level ON level.id = other.admin_level_id
    WHERE other.id <> v_target_id
      AND other.is_active IS TRUE
      AND other.deleted_at IS NULL
      AND lower(btrim(level.code)) = 'township'
      AND other.geom IS NOT NULL
      AND NOT ST_IsEmpty(other.geom)
      AND ST_IsValid(other.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom)
       OR ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon'
       OR v_removed_m2 > 1.0
       OR v_outside_mimu_m2 > 1.0
       OR v_outside_approved_m2 > 1.0
       OR v_precovered_m2 > 1.0
       OR v_new_overlap_m2 > 100.0
       OR v_area_added_m2 < 100.0 THEN
        INSERT INTO _safe_review_results (
            group_id, township_id, canonical_name, mimu_pcode, status,
            best_candidate_id, best_score, second_score, area_added_m2,
            new_overlap_m2, reason
        )
        VALUES (
            v_group_id, v_target_id, v_before.canonical_name, v_mimu_pcode, 'skipped',
            v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
            v_new_overlap_m2,
            format(
                'proposed geometry failed safety checks: removed=%s outside_mimu=%s outside_approved=%s precovered=%s overlap=%s',
                v_removed_m2, v_outside_mimu_m2, v_outside_approved_m2,
                v_precovered_m2, v_new_overlap_m2
            )
        );
        RETURN;
    END IF;

    -- Deliberately update geom only. Any updated_at change is trigger-controlled.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.* INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other
       OR NOT ST_CoveredBy(v_before.geom, v_after.geom)
       OR NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update invariant validation', v_target_id;
    END IF;

    INSERT INTO _safe_review_results (
        group_id, township_id, canonical_name, mimu_pcode, status,
        best_candidate_id, best_score, second_score, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_group_id, v_target_id, v_after.canonical_name, v_mimu_pcode, 'updated',
        v_best_candidate_id, v_best_score, v_second_score, v_area_added_m2,
        v_new_overlap_m2,
        'latest approved live-gap intersection added; old surface preserved'
    );
END
$safe_review$;

DO $safe_review$
DECLARE
    v_group_id constant text := 'RG-0051';
    v_target_id constant bigint := 6620;
    v_expected_name constant text := 'ဟုန်ရှင်းမြို့နယ်';
    v_mimu_pcode constant text := 'MMR015023';
    v_expected_parent_id constant bigint := 6411;
    v_expected_state_id constant bigint := 6329;
    v_expected_geom_hash constant text := '191092938ed519eadf520454fea8bfdc';
    v_expected_other constant jsonb := '{"address_confidence_score":50,"address_usage":"official","admin_area_type_id":8,"admin_level_id":4,"boundary_confidence_score":80,"boundary_note":null,"boundary_status":"official","canonical_name":"ဟုန်ရှင်းမြို့နယ်","centroid":{"coordinates":[98.66859786323977,24.030344],"crs":{"properties":{"name":"EPSG:4326"},"type":"name"},"type":"Point"},"created_at":"2026-06-04T18:46:45.439775+00:00","deleted_at":null,"external_id":"osm:R:17024480","geometry_source":null,"id":6620,"is_active":true,"is_official_boundary":true,"is_public_usable":true,"is_verified":true,"normalized_data":{"admin_level":"7","area_m2":481559542.44616246,"boundary":"administrative","level_correction_applied":true,"mapped_admin_level_code":"township","names":[{"admin_area_candidate_id":13123,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024480","id":4895,"is_primary":true,"language_code":"und","name":"ဟုန်ရှင်းမြို့နယ် 红星区","name_type":"official","normalized_data":{"source_tag":"name"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17024480","raw_id":11112,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name"},"source_tag":"name"},{"admin_area_candidate_id":13123,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024480","id":4896,"is_primary":true,"language_code":"en","name":"Hongxing Township","name_type":"official","normalized_data":{"source_tag":"name:en"},"search_weight":100,"source_refs":{"osm_feature_type":"R","osm_id":"17024480","raw_id":11112,"raw_table":"raw_osm_polygons","snapshot_version":"osm_myanmar_2026_06_02_admin_fast_v1","source_snapshot_id":6,"source_tag":"name:en"},"source_tag":"name:en"},{"admin_area_candidate_id":13123,"created_at":"2026-06-03T16:47:35.744582+00:00","external_id":"osm:R:17024480","id":4897,"is_primary":true,"language_code":"my","name":"ဟုန်ရှင်းမြို့နယ်","name_type":"official","no